mapper.select:
select e.*, d.name deptName, r.name roleName from emp e left join dept d on e.dept_id = d.id left join sys_role r on e.role_id = r.id
e.name like concat('%',#{name},'%')
and e.gender = #{gender}
and e.entry_date between #{begin} and #{end}
order by e.update_time desc

mapper.update:
update emp
username = #{username}, name = #{name}, gender = #{gender}, phone = #{phone}, job = #{job}, salary = #{salary}, image = #{image}, entry_date = #{entryDate}, dept_id = #{deptId}, role_id = #{roleId}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select if(gender = 1, '男性员工', '女性员工') name,
count(*) value
from emp group by gender;
